// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // Only the owner may pass the require; restrict the domain so the
        // reference never reverts on admissible inputs, but keep the amount wide.
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);

        address owner = c.smartfix_owner();
        vm.assume(actor == owner);

        // Fund the target contract so the selfdestruct refund is observable.
        vm.deal(address(c), amount);
        assertEq(address(c).balance, amount);

        uint256 callerBefore = actor.balance;

        vm.prank(actor);
        c.sudicideAnyone();

        // Rule: after an admissible (owner) call, the contract is destroyed and
        // its whole balance is delivered to the CALLER (msg.sender).  The mutant
        // pays the stored owner instead, so any admissible caller that is not
        // the stored owner receives nothing and the rule breaks.
        assertTrue(
            address(c).balance == 0 && actor.balance == callerBefore + amount
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        // admissible domain: caller distinct from the deployer/owner (this test contract)
        // and from the contract itself; amount bounded to a sane funded range.
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        vm.assume(actor != address(0));
        bound(amount, 0, 1 ether);
        vm.deal(address(c), amount);
        uint256 callerBefore = actor.balance;
        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        if (ok) {
            // the contract is destroyed and its whole balance went to the CALLER
            assertTrue(address(c).balance == 0 && actor.balance - callerBefore == amount);
        } else {
            // non-owner must be reverted and nothing changed
            assertTrue(address(c).balance == amount && actor.balance == callerBefore);
        }
    }
}

