pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // keep the domain wide: any non-zero actor, any amount (including 0)
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, type(uint256).max / 2);

        // fund the contract under test so the refund destination is observable
        vm.deal(address(c), amount);
        uint256 callerBalanceBefore = actor.balance;

        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful call may only come from the owner; in the
        // reference contract the caller IS the owner in that case, so the entire
        // balance must leave the contract (destroyed). The mutant routes the
        // refund to the stored owner instead of msg.sender, so for a caller the
        // mutant treats as owner the funds land at the stored owner while the
        // caller is left out, and for any admissible caller distinct from the
        // stored owner the observable post-state (contract balance / caller
        // enrichment) diverges.
        assertTrue(
            !ok || (address(c).balance == 0 && actor.balance >= callerBalanceBefore),
            "successful sudicideAnyone must destroy the contract and enrich its caller"
        );
    }
}

