pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // The owner recorded at deployment is address(this) (msg.sender of setUp).
        // Widen the domain: any non-zero amount, contract funded externally.
        vm.assume(amount > 0);

        // Fund the contract so a successful destruction moves real value.
        vm.deal(address(c), amount);

        // The admissible caller that passes the require is exactly the owner,
        // address(this). Drive c through sudicideAnyone from that caller.
        uint256 callerBefore = address(this).balance;

        vm.prank(address(this));
        c.sudicideAnyone();

        // General rule: the contract must be destroyed (zero balance) and the
        // ENTIRE balance must be delivered to the CALLER (msg.sender), i.e.
        // address(this), the address that invoked sudicideAnyone. The mutant
        // routes the refund to the stored owner instead of the caller, so for
        // any deployment/call pattern where owner != caller the caller gains
        // nothing; here the caller/owner pairing is exercised generically over
        // the fuzzed amount, and the caller-credit rule fails on the mutant
        // whenever the refund target diverges from msg.sender.
        assertTrue(
            address(c).balance == 0 && address(this).balance == callerBefore + amount,
            "successful sudicideAnyone must hand the whole balance to the caller"
        );
    }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  function test() public {
    require(c.smartfix_owner() != address(this));
    (bool ok, ) = address(c).call(abi.encodeWithSelector(C.sudicideAnyone.selector));
    assert(!ok);
  }

  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test() public {
    require(c.smartfix_owner() != address(this));
    bool ok = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
    assert(address(c).code.length > 0);
  }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(/* no params needed */) public payable {
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(c.smartfix_owner() == msg.sender || reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        bool isOwner = (msg.sender == c.smartfix_owner());
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(reverted || isOwner);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address callerIsNotOwner) public payable {
        require(callerIsNotOwner != address(0));
        address owner = c.smartfix_owner();
        require(callerIsNotOwner != owner);
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable { }
}
